    )
    new_paid = row["paid_cents"] + amount_cents
    return {
        "record_id": record_id,
        "paid_cents": new_paid,
        "outstanding_cents": row["amount_cents"] - new_paid,
        "status": "settled" if new_paid >= row["amount_cents"] else "accepted",
    }


